window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[167]={"id":"167","numero":167,"titre":"Hépatites virales","objectifs":[{"id":"167-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition d’une hépatite","contenu":"<p>Une <span class=\"kw-def\">hépatite</span> est une <span class=\"kw-def\">inflammation du foie</span>. Elle se décèle de deux façons : soit par une <span class=\"kw-bio\">élévation des transaminases (ASAT / ALAT)</span> traduisant la <span class=\"kw-def\">nécrose des hépatocytes</span>, soit par une <span class=\"kw-bio\">cholestase</span> — une forme mixte cytolytique / cholestatique est possible.</p>\n      <table >\n        <thead><tr><th>Forme</th><th>Durée</th><th>Particularité</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-def\">Hépatite</span> aiguë</strong></td><td><span class=\"kw-chiffre\">&lt; 6 mois</span></td><td>Transaminases souvent <span class=\"kw-chiffre\">&gt; 10 N</span> ; le terme est réservé à un foie <strong>antérieurement sain</strong></td></tr>\n          <tr><td><strong><span class=\"kw-def\">Hépatite</span> chronique</strong></td><td><span class=\"kw-chiffre\">&gt; 6 mois</span></td><td>Transaminases souvent <span class=\"kw-chiffre\">&lt; 5 N</span></td></tr>\n        </tbody>\n      </table>\n      <p>L'<span class=\"kw-def\">insuffisance hépatique aiguë (IHA)</span> se définit comme une dysfonction hépatique évoluant en général en <span class=\"kw-chiffre\">&lt; 3 mois</span>, survenant <strong>sur foie sain</strong>. À distinguer de l'<span class=\"kw-def\">IHA-sur-chronique</span> = <span class=\"kw-alerte\">décompensation</span> d'une <span class=\"kw-def\">cirrhose</span> sous-jacente sur un événement aigu intercurrent.</p>\n      <div class=\"callout callout-warn\"><strong>Piège de vocabulaire :</strong> préférer « <span class=\"kw-bio\">élévation des transaminases</span> » ou « hypertransaminasémie » au terme « cytolyse hépatique » — la <span class=\"kw-bio\">cholestase</span> élève aussi régulièrement <span class=\"kw-clinique\">les</span> transaminases <strong>sans <span class=\"kw-clinique\">nécrose</span> hépatocytaire</strong>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 278 — <span class=\"kw-clinique\">Ictère</span> · 279 — <span class=\"kw-def\">Cirrhose</span></em></p>","frequence":1},{"id":"167-2","rang":"A","rubrique":"Epidémiologie","titre":"Connaître les modes de transmission et la prévalence mondiale des différentes hépatites virales","contenu":"<p><span class=\"kw-clinique\">Les</span> modes de transmission opposent deux groupes : <span class=\"kw-etio\">VHA et VHE</span> (virus <strong>nus</strong>), à transmission <span class=\"kw-def\">oro-fécale</span>, et <span class=\"kw-etio\">VHB / VHC / VHD</span> (virus <strong>enveloppés</strong>, fragiles dans le milieu extérieur, <strong>jamais</strong> de transmission <span class=\"kw-def\">oro-fécale</span>).</p>\n      <table >\n        <thead><tr><th>Voie</th><th><span class=\"kw-etio\">VHA</span></th><th><span class=\"kw-etio\">VHB</span></th><th><span class=\"kw-etio\">VHC</span></th><th><span class=\"kw-etio\">VHD</span></th><th><span class=\"kw-etio\">VHE</span></th></tr></thead>\n        <tbody>\n          <tr><td>Oro-fécale</td><td><strong>+++</strong></td><td>Non</td><td>Non</td><td>Non</td><td><strong>+++</strong></td></tr>\n          <tr><td>Sexuelle</td><td>Si rapports oro-anaux</td><td><strong>+++</strong></td><td><strong>+++</strong></td><td><strong>+++</strong></td><td>Non</td></tr>\n          <tr><td>Parentérale</td><td>+</td><td><strong>+++</strong></td><td><strong>+++</strong></td><td><strong>+++</strong></td><td>+</td></tr>\n          <tr><td>Materno-fœtale</td><td>Non</td><td><strong>+++</strong></td><td>↑ si co-infection <span class=\"kw-bio\">VIH</span></td><td>+</td><td>Non</td></tr>\n        </tbody>\n      </table>\n      <p><strong><span class=\"kw-def\">Prévalence</span> mondiale :</strong></p>\n      <ul>\n        <li><strong><span class=\"kw-etio\">VHB</span></strong> : <span class=\"kw-chiffre\">250 millions</span> de porteurs chroniques dans le monde ; en France <span class=\"kw-chiffre\">7 %</span> de la population a été en <span class=\"kw-def\">contact</span>, dont <span class=\"kw-chiffre\">280 000</span> infections chroniques.</li>\n        <li><strong><span class=\"kw-etio\">VHC</span></strong> : <span class=\"kw-def\">prévalence</span> mondiale de l'infection chronique <span class=\"kw-chiffre\">≈ 3 %</span> (190 millions) ; forte prévalence en <strong>Égypte</strong>, gradient Nord-Sud.</li>\n        <li><strong><span class=\"kw-etio\">VHA</span></strong> : large réservoir dans <span class=\"kw-clinique\">les</span> pays en voie de développement ; la <strong>France est un pays à faible risque endémique</strong>.</li>\n      </ul>\n      <p><strong>Règles d'hygiène et de santé publique :</strong></p>\n      <table >\n        <thead><tr><th>Mesure</th><th>Virus ciblé(s)</th></tr></thead>\n        <tbody>\n          <tr><td>Lutte contre le <strong><span class=\"kw-def\">péril fécal</span></strong> — hygiène des mains, de l'eau et des aliments</td><td><span class=\"kw-etio\">VHA</span>, VHE</td></tr>\n          <tr><td><strong>Cuisson à cœur</strong> du porc, du sanglier et du gibier</td><td><span class=\"kw-etio\">VHE</span></td></tr>\n          <tr><td><strong>Rapports sexuels protégés</strong></td><td><span class=\"kw-etio\">VHB</span>, <span class=\"kw-etio\">VHC</span></td></tr>\n          <tr><td><strong>Matériel d'injection à usage unique</strong> chez <span class=\"kw-clinique\">les</span> usagers de drogues IV</td><td><span class=\"kw-etio\">VHB</span>, <span class=\"kw-etio\">VHC</span>, VHD</td></tr>\n          <tr><td><strong><span class=\"kw-def\">Dépistage</span> des dons du sang</strong> — transaminases, <span class=\"kw-bio\">marqueurs viraux</span></td><td><span class=\"kw-etio\">VHB</span>, <span class=\"kw-etio\">VHC</span> ± VHE</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Déclaration obl<span class=\"kw-chiffre\">iga</span>toire :</strong> l'<span class=\"kw-alerte\">hépatite A aiguë</span> et l'<span class=\"kw-alerte\">hépatite B aiguë symptomatique</span> sont des maladies à <span class=\"kw-alerte\">déclaration obligatoire</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 175 — Voyage en pays tropical · 169 — <span class=\"kw-etio\">VIH</span></em></p>","frequence":4},{"id":"167-3","rang":"A","rubrique":"Epidémiologie","titre":"Connaître les différents virus (A → E)","contenu":"<p>Cinq <span class=\"kw-etio\">virus hépatotropes</span> sont à connaître. Le point discriminant majeur : <span class=\"kw-alerte\">le VHB est le seul virus à ADN</span> — donc le seul potentiellement oncogène, capable de provoquer un <span class=\"kw-alerte\">CHC sans cirrhose préalable</span>.</p>\n      <table >\n        <thead><tr><th>Virus</th><th>Génome</th><th>Incubation</th><th>Famille / particularité</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-etio\">VHA</span></strong></td><td><span class=\"kw-def\">ARN simple brin, nu</span></td><td><span class=\"kw-chiffre\">10-45 j</span></td><td>Genre <em>Hepatovirus</em> ; <strong>non</strong> directement cytopathogène (lésions immuno-médiées)</td></tr>\n          <tr><td><strong><span class=\"kw-etio\">VHB</span></strong></td><td><span class=\"kw-def\">ADN circulaire double brin</span>, enveloppé</td><td><span class=\"kw-chiffre\">2-4 mois</span></td><td><em>Hepadnavirus</em> ;<span class=\"kw-chiffre\"> 4 g</span>ènes (S, C, P, X) ; <span class=\"kw-alerte\">seul virus à ADN → oncogène</span></td></tr>\n          <tr><td><strong><span class=\"kw-etio\">VHC</span></strong></td><td><span class=\"kw-def\">ARN simple brin, enveloppé</span></td><td><span class=\"kw-chiffre\">15 j-3 mois</span></td><td><em>Flavivirus</em> ;<span class=\"kw-chiffre\"> 6 g</span>énotypes ; <strong>directement cytopathogène</strong>, mais charge <span class=\"kw-etio\">virale</span> <strong>non corrélée</strong> à la fibrose</td></tr>\n          <tr><td><strong><span class=\"kw-etio\">VHD</span></strong></td><td><span class=\"kw-def\">ARN circulaire, défectif</span></td><td><span class=\"kw-chiffre\">30-45 j</span></td><td>Dépend du <span class=\"kw-etio\">VHB</span> pour se multiplier — <strong>pas d'infection <span class=\"kw-etio\">VHD</span> sans VHB</strong></td></tr>\n          <tr><td><strong><span class=\"kw-etio\">VHE</span></strong></td><td><span class=\"kw-def\">ARN monocaténaire, nu</span></td><td><span class=\"kw-chiffre\">10-40 j</span></td><td>Transmission <span class=\"kw-def\">oro-fécale</span> et zoonotique</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Discriminant clé :</strong> <span class=\"kw-alerte\">VHB oncogène → CHC possible sans cirrhose</span>. <span class=\"kw-clinique\">Les</span> autres virus ne donnent un CHC qu'<strong>après <span class=\"kw-def\">cirrhose</span> constituée</strong>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 279 — <span class=\"kw-def\">Cirrhose</span> · 304 — Tumeur du foie</em></p>","frequence":2},{"id":"167-4","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les principales causes d’élévation des transaminases en dehors de l’infection virale","contenu":"<p>Devant une élévation des transaminases sans cause <span class=\"kw-etio\">virale</span>, l'amplitude oriente le raisonnement : élévation <strong>modérée</strong> (<span class=\"kw-chiffre\">&lt; 5-10 N</span>) <span class=\"kw-bio\">vs</span> <strong>importante</strong> (<span class=\"kw-chiffre\">&gt; 10 N</span>).</p>\n      <table >\n        <thead><tr><th>Amplitude</th><th>Étiologies évocatrices</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Modérée (&lt; 5-10 N)</strong></td><td>Stéato-<span class=\"kw-def\">hépatite</span> alcoolique ; <span class=\"kw-def\">syndrome métabolique</span> ; <span class=\"kw-etio\">hémochromatose</span></td></tr>\n          <tr><td><strong>Importante (&gt; 10 N)</strong></td><td><span class=\"kw-def\">Hépatite</span> <span class=\"kw-etio\">toxique</span> ; <span class=\"kw-def\">hépatite</span> <span class=\"kw-etio\">auto-immune</span> ; <span class=\"kw-def\">hépatite</span> hypoxique (foie de <span class=\"kw-alerte\">choc</span>, Budd-Chiari) ; <span class=\"kw-etio\">maladie de Wilson</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Classement par mécanisme :</strong></p>\n      <table >\n        <thead><tr><th>Mécanisme</th><th>Causes</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Métabolique</strong></td><td>Stéatopathie métabolique (rechercher un <span class=\"kw-def\">syndrome métabolique</span>)</td></tr>\n          <tr><td><strong>Toxiques</strong></td><td><span class=\"kw-ttt\">Paracétamol</span> (toxicité directe ou immuno-<span class=\"kw-etio\">allergique</span>) ; <strong>amanite phalloïde</strong>, lépiotes ; <strong>ecstasy, cocaïne</strong> ; phytothérapie, compléments alimentaires ; <br>l'<span class=\"kw-etio\">alcool</span> seul ne dépasse pas <span class=\"kw-chiffre\">10 N</span></td></tr>\n          <tr><td><strong>Mise en pression hépatocytaire</strong></td><td><strong>Biliaire :</strong> lithiase, compression ; <br><strong>Vasculaire :</strong> thrombose porte, thrombose des veines sus-hépatiques, foie de <span class=\"kw-alerte\">choc</span>, <span class=\"kw-etio\">insuffisance cardiaque</span> ; <br><strong>Ischémie :</strong> <span class=\"kw-alerte\">état de choc</span>, thromboses splanchniques</td></tr>\n          <tr><td><strong><span class=\"kw-ci\">Grossesse</span></strong></td><td><span class=\"kw-alerte\">HELLP syndrome</span> ; <span class=\"kw-alerte\">stéatose aiguë gravidique</span></td></tr>\n          <tr><td><strong><span class=\"kw-etio\">Auto-immune</span> / métabolique rare</strong></td><td><span class=\"kw-def\">Hépatite</span> <span class=\"kw-etio\">auto-immune</span> (<span class=\"kw-bio\">AAN</span>, <span class=\"kw-bio\">anti-muscle lisse</span>, <span class=\"kw-bio\">anti-LKM</span>, <span class=\"kw-bio\">anti-SLA</span>, <span class=\"kw-bio\">IgG</span>) ; <span class=\"kw-etio\">maladie de Wilson</span> ; hémochromatose ; déficit en α1-antitrypsine ; leptospirose, <span class=\"kw-clinique\">syphilis</span></td></tr>\n          <tr><td><strong>Extra-hépatiques</strong></td><td><span class=\"kw-etio\">Maladie cœliaque</span> ; hémolyse ; atteinte musculaire — prédomine alors sur <span class=\"kw-clinique\">les</span> <span class=\"kw-bio\">ASAT</span>, <strong>doser les <span class=\"kw-bio\">CPK</span></strong> pour faire la différence</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 279 — <span class=\"kw-def\">Cirrhose</span></em></p>","frequence":2},{"id":"167-5","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître les examens biologiques de première intention devant une hépatite aiguë","contenu":"<p>Devant une <span class=\"kw-def\">hépatite</span> aiguë (élévation forte des transaminases), le bilan de <strong>1ʳᵉ intention</strong> associe <span class=\"kw-bio\">sérologies</span> virales, <span class=\"kw-def\">dépistage</span> <span class=\"kw-etio\">toxique</span> et imagerie.</p>\n      <table >\n        <thead><tr><th>Examen</th><th>Recherche</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-bio\">IgM anti-VHA</span></td><td>Infection aiguë par le <span class=\"kw-etio\">VHA</span></td></tr>\n          <tr><td><span class=\"kw-bio\">Ac anti-VHC ± ARN VHC</span></td><td>Infection aiguë par le <span class=\"kw-etio\">VHC</span> — <strong><span class=\"kw-clinique\">les</span> Ac seuls n'éliminent pas</strong> une <span class=\"kw-def\">hépatite</span> C aiguë</td></tr>\n          <tr><td><span class=\"kw-bio\">AgHBs</span></td><td>Infection par le <span class=\"kw-etio\">VHB</span>. Si positif : <span class=\"kw-bio\">IgM anti-HBc + ADN VHB</span>, puis chercher une surinfection delta (<span class=\"kw-bio\">IgM anti-delta, ARN delta</span>)</td></tr>\n          <tr><td><span class=\"kw-bio\">IgM anti-VHE</span></td><td>Infection aiguë par le <span class=\"kw-etio\">VHE</span></td></tr>\n          <tr><td><span class=\"kw-imagerie\">Échographie hépatique</span></td><td>Migration lithiasique ; maladie chronique du foie ; thrombose des veines hépatiques ou de la veine porte</td></tr>\n        </tbody>\n      </table>\n      <p><strong><span class=\"kw-def\">Dépistage</span> <span class=\"kw-etio\">toxique</span> :</strong> alcoolémie, recherche urinaire de cocaïne / amphétamine, <span class=\"kw-ttt\">paracétamolémie</span> (interprétée selon le délai de la prise, nomogramme de <strong>Rumack et Matthew</strong>).</p>\n      <div class=\"callout callout-info\"><strong>À savoir :</strong> une <span class=\"kw-ttt\">paracétamolémie</span> nulle <strong>n'élimine pas</strong> l'intoxication si le dosage est réalisé tardivement.</div>\n      <p><strong>Examens de 2ᵉ intention :</strong> <span class=\"kw-bio\">PCR HSV</span> si <span class=\"kw-chiffre\">fièvre &gt; 38,5 °C</span> ; bilan d'<span class=\"kw-def\">hépatite</span> <span class=\"kw-etio\">auto-immune</span> ; <span class=\"kw-bio\">céruloplasminémie / cuprurie</span> (Wilson) ; <span class=\"kw-bio\">IgM CMV, anti-VCA, VZV</span> ; <span class=\"kw-imagerie\">ETT</span> dès qu'une atteinte hépatique <span class=\"kw-etio\">ischémique</span> est évoquée (foie de <span class=\"kw-alerte\">choc</span>, <span class=\"kw-etio\">insuffisance cardiaque</span> droite).</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 278 — <span class=\"kw-clinique\">Ictère</span></em></p>","frequence":1},{"id":"167-6","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître les examens biologiques de première intention devant une hépatite chronique","contenu":"<p>Une <span class=\"kw-def\">hépatite</span> chronique se confirme par la <strong>persistance &gt; <span class=\"kw-chiffre\">6 mois</span></strong> des anomalies : <span class=\"kw-bio\">AgHBs positif &gt; 6 mois</span> pour le <span class=\"kw-etio\">VHB</span>, <span class=\"kw-bio\">PCR ARN VHC positive &gt; 6 mois</span> pour le <span class=\"kw-etio\">VHC</span>.</p>\n      <p><strong>Interprétation de la <span class=\"kw-bio\">sérologie</span> <span class=\"kw-etio\">VHB</span> :</strong></p>\n      <table >\n        <thead><tr><th>AgHBs</th><th><span class=\"kw-bio\">Ac anti-HBs</span></th><th><span class=\"kw-bio\">Ac anti-HBc</span></th><th>Interprétation</th></tr></thead>\n        <tbody>\n          <tr><td>−</td><td>+</td><td>−</td><td><span class=\"kw-def\">Vacciné</span> (<span class=\"kw-ttt\">vaccination</span> efficace si anti-HBs <span class=\"kw-chiffre\">&gt; 10 UI/L</span>)</td></tr>\n          <tr><td>−</td><td>+</td><td>+</td><td><span class=\"kw-def\">Infection guérie</span></td></tr>\n          <tr><td>+</td><td>−</td><td><span class=\"kw-chiffre\">IgM</span> +</td><td><span class=\"kw-def\">Hépatite aiguë B</span></td></tr>\n          <tr><td>+</td><td>−</td><td><span class=\"kw-chiffre\">IgG</span> +</td><td><span class=\"kw-def\">Portage chronique</span> → doser AgHBe + ADN <span class=\"kw-etio\">VHB</span> pour guider la PEC</td></tr>\n          <tr><td>−</td><td>−</td><td>+</td><td><span class=\"kw-def\">Anti-HBc isolé</span> : infection guérie ancienne (le plus fréquent) ou <span class=\"kw-alerte\">infection occulte / fenêtre sérologique</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Bilan de prise en charge commun B / C :</strong></p>\n      <ul>\n        <li><span class=\"kw-bio\">NFS</span>, <span class=\"kw-bio\">bilan hépatique</span>, <span class=\"kw-bio\">albuminémie</span>.</li>\n        <li>Hémostase : <span class=\"kw-bio\">TP</span>, <span class=\"kw-bio\">facteur V</span> si <span class=\"kw-bio\">TP</span> &lt; <span class=\"kw-chiffre\">70 %</span>, <span class=\"kw-bio\">INR</span> si <span class=\"kw-def\">cirrhose</span> (calcul du <span class=\"kw-def\">score</span> <span class=\"kw-chiffre\">MELD</span>).</li>\n        <li><span class=\"kw-bio\">Sérologie</span> <span class=\"kw-bio\">VIH</span> (co-infection fréquente).</li>\n      </ul>\n      <p><strong>Évaluation de la fibrose :</strong> marqueurs sériques indirects (<span class=\"kw-bio\">FibroTest, FibroMètre, Hépascore</span>), élasticité hépatique (<span class=\"kw-imagerie\">Fibroscan</span>) ou <span class=\"kw-def\">score</span> histologique <span class=\"kw-def\">METAVIR</span> après <span class=\"kw-imagerie\">PBH</span> — activité A0-A3, fibrose F0-F4. <span class=\"kw-alerte\">La PBH n'est pas recommandée si VHC chronique sans comorbidité</span>.</p>\n      <p><strong><span class=\"kw-def\">Dépistage</span> du CHC :</strong> <span class=\"kw-imagerie\">échographie</span> (dépistage) / <span class=\"kw-imagerie\">IRM hépatique</span> (confirmation) — tous <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">6 mois si cirrhose</span>, tous les <span class=\"kw-chiffre\">2 ans si hépatite chronique sans cirrhose</span>. <span class=\"kw-imagerie\">FOGD</span> à la recherche de varices œsogastriques.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 279 — <span class=\"kw-def\">Cirrhose</span> · 304 — Tumeur du foie · 169 — <span class=\"kw-etio\">VIH</span></em></p>","frequence":4},{"id":"167-7","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les manifestations extra hépatiques des hépatites chroniques","contenu":"<p><span class=\"kw-clinique\">Les</span> hépatites chroniques B et C ont des <span class=\"kw-def\">manifestations extra-hépatiques</span> distinctes, le plus souvent à médiation immunologique.</p>\n      <table >\n        <thead><tr><th>Virus</th><th>Manifestations extra-hépatiques</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-etio\">VHB</span></strong></td><td><span class=\"kw-clinique\">Périartérite noueuse</span> (précoce) ; <span class=\"kw-clinique\">glomérulonéphrite extra-membraneuse (GEM)</span> ++ ; glomérulonéphrite membrano-proliférative</td></tr>\n          <tr><td><strong><span class=\"kw-etio\">VHC</span></strong></td><td><span class=\"kw-clinique\">Cryoglobulinémie</span> (<span class=\"kw-chiffre\">20-50 %</span>) ; <span class=\"kw-etio\">vascularite</span> ; syndrome sec ; <span class=\"kw-def\">hépatite</span> <span class=\"kw-etio\">auto-immune</span> ; GEM / GN membrano-proliférative (<span class=\"kw-chiffre\">20 %</span>) ; porphyrie cutanée tardive ; <span class=\"kw-clinique\">lymphome de la zone marginale splénique</span> (LNH)</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 192 — Pathologie <span class=\"kw-etio\">auto-immune</span> · 193 — <span class=\"kw-etio\">Vascularite</span> systémique · 261 — Néphropathie glomérulaire · 319 — Lymphome malin</em></p>","frequence":0},{"id":"167-8","rang":"A","rubrique":"Identifier une urgence","titre":"Connaître les signes de gravité d’une hépatite aiguë","contenu":"<p>Deux niveaux de gravité doivent être distingués devant une <span class=\"kw-def\">hépatite</span> aiguë.</p>\n      <table >\n        <thead><tr><th>Niveau</th><th>Définition</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-def\">Hépatite</span> sévère</strong></td><td><span class=\"kw-alerte\">TP &lt; 50 %</span> ou <span class=\"kw-alerte\">facteur V &lt; 50 %</span>, <strong>en l'absence d'encéphalopathie</strong> — ou <span class=\"kw-clinique\">ictère</span> prolongé</td></tr>\n          <tr><td><strong><span class=\"kw-def\">Hépatite</span> grave / fulminante</strong></td><td>Apparition d'une <span class=\"kw-alerte\">encéphalopathie hépatique</span> : <strong>fulminante</strong> si <span class=\"kw-chiffre\">&lt; 15 jours</span> après l'<span class=\"kw-clinique\">ictère</span>, <strong>subfulminante</strong> entre <span class=\"kw-chiffre\">15 jours et 3 mois</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Gradation de l'<span class=\"kw-alerte\">encéphalopathie hépatique</span> :</strong></p>\n      <table >\n        <thead><tr><th><span class=\"kw-def\">Stade</span></th><th>Tableau</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-def\">Stade</span> 1</strong></td><td><span class=\"kw-clinique\">Astérixis</span> + altération du cycle veille / sommeil</td></tr>\n          <tr><td><strong><span class=\"kw-def\">Stade</span> 2</strong></td><td><span class=\"kw-clinique\">Confusion</span></td></tr>\n          <tr><td><strong><span class=\"kw-def\">Stade</span> 3</strong></td><td><span class=\"kw-clinique\">Coma</span> vigil — <span class=\"kw-chiffre\">Glasgow 10-13</span></td></tr>\n          <tr><td><strong><span class=\"kw-def\">Stade</span> 4</strong></td><td><span class=\"kw-clinique\">Coma</span> profond — <span class=\"kw-chiffre\">Glasgow 3-9</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Autres <span class=\"kw-alerte\">signes de gravité</span> :</strong> <span class=\"kw-bio\">hypoglycémie</span> (hyperinsulinisme secondaire + diminution de la néoglucogenèse), <span class=\"kw-bio\">hyperlactatémie</span>, <span class=\"kw-clinique\">ascite</span>, <span class=\"kw-alerte\">syndrome hémorragique</span>, <span class=\"kw-clinique\">hypotension</span> / <span class=\"kw-clinique\">tachycardie</span> / <span class=\"kw-alerte\">défaillance</span> multiviscérale, hyperventilation précoce (<span class=\"kw-bio\">alcalose respiratoire</span> habituelle).</p>\n      <p><strong>Terrains à risque de forme grave :</strong> <span class=\"kw-alerte\">femme enceinte au 3ᵉ trimestre</span> (<span class=\"kw-etio\">VHE</span> — <span class=\"kw-def\">hépatite</span> fulminante ≈ <span class=\"kw-chiffre\">20 %</span>, mort in utero), enfant, <span class=\"kw-alerte\">hépatopathie chronique préexistante</span>.</p>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-alerte\">Urgence</span> :</strong> devant une IHA grave / fulminante → <strong><span class=\"kw-def\">contact</span> précoce avec un centre expert</strong> et discussion d'une <span class=\"kw-alerte\">transplantation hépatique en super-urgence</span>. Le <span class=\"kw-etio\">VHC</span> ne donne <strong>quasiment jamais</strong> d'<span class=\"kw-def\">hépatite</span> fulminante.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 279 — <span class=\"kw-def\">Cirrhose</span></em></p>","frequence":1},{"id":"167-9","rang":"A","rubrique":"Suivi et/ou pronostic","titre":"Connaître le mode évolutif des hépatites virales","contenu":"<p>Le mode évolutif est <strong>le point le plus rentable</strong> de l'item : risque de chronicité, de <span class=\"kw-def\">cirrhose</span> et de CHC propre à chaque virus.</p>\n      <table >\n        <thead><tr><th>Virus</th><th>Chronicité</th><th><span class=\"kw-def\">Cirrhose</span></th><th>CHC</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-etio\">VHA</span></strong></td><td><span class=\"kw-clinique\">Jamais</span> (guérison <span class=\"kw-chiffre\">100 %</span>)</td><td>—</td><td>—</td></tr>\n          <tr><td><strong><span class=\"kw-etio\">VHB</span></strong></td><td><span class=\"kw-chiffre\">5-10 %</span></td><td><span class=\"kw-chiffre\">10-20 %</span></td><td><span class=\"kw-alerte\">3-5 %/an, même sans cirrhose</span></td></tr>\n          <tr><td><strong><span class=\"kw-etio\">VHC</span></strong></td><td><span class=\"kw-chiffre\">65-85 %</span></td><td><span class=\"kw-chiffre\">10-20 %</span></td><td><span class=\"kw-chiffre\">3-5 %/an, seulement après cirrhose</span></td></tr>\n          <tr><td><strong><span class=\"kw-etio\">VHD</span></strong></td><td colspan=\"3\"><span class=\"kw-clinique\">Évolution</span> parallèle au <span class=\"kw-etio\">VHB</span> (augmente son risque de <span class=\"kw-def\">cirrhose</span> et de CHC)</td></tr>\n          <tr><td><strong><span class=\"kw-etio\">VHE</span></strong></td><td>Seulement chez l'<span class=\"kw-alerte\">immunodéprimé</span></td><td>—</td><td>—</td></tr>\n        </tbody>\n      </table>\n      <p>Le risque de <strong>chronicité du <span class=\"kw-etio\">VHB</span> dépend de l'âge</strong> à la contamination : <span class=\"kw-chiffre\">90 % chez le nouveau-né</span>, <span class=\"kw-chiffre\">30 % chez l'enfant</span>, <span class=\"kw-chiffre\">10 % chez l'adulte</span>.</p>\n      <p><strong>Guérison spontanée d'une <span class=\"kw-def\">hépatite</span> aiguë :</strong> <span class=\"kw-chiffre\">≈ 90 %</span> pour le <span class=\"kw-etio\">VHB</span> (chronicité dans <span class=\"kw-chiffre\">10 %</span>), <span class=\"kw-chiffre\">15-35 %</span> seulement pour le <span class=\"kw-etio\">VHC</span> — d'où le grand réservoir de porteurs chroniques.</p>\n      <p><strong><span class=\"kw-etio\">VHD</span> :</strong> la <strong>co-infection</strong> (B + D simultanée) guérit quasi systématiquement ; la <strong>surinfection</strong> d'un porteur <span class=\"kw-etio\">VHB</span> chronique évolue vers une <span class=\"kw-def\">hépatite</span> chronique D, avec risque de <span class=\"kw-def\">cirrhose</span> et de <span class=\"kw-alerte\">CHC</span>.</p>\n      <p><strong><span class=\"kw-clinique\">Les</span> 4 phases de l'<span class=\"kw-def\">hépatite</span> B chronique :</strong></p>\n      <table >\n        <thead><tr><th>Phase</th><th>ADN <span class=\"kw-etio\">VHB</span></th><th>AgHBe</th><th>Transaminases</th></tr></thead>\n        <tbody>\n          <tr><td><strong>1. Tolérance immunitaire</strong></td><td><span class=\"kw-chiffre\">&gt; 8 log UI/mL</span></td><td>+</td><td>Normales</td></tr>\n          <tr><td><strong>2. <span class=\"kw-bio\">Clairance</span> immunitaire</strong></td><td><span class=\"kw-chiffre\">&lt; 8 log UI/mL</span></td><td>+</td><td>Élevées</td></tr>\n          <tr><td><strong>3. Portage inactif</strong></td><td><span class=\"kw-chiffre\">&lt; 2000 UI/mL</span></td><td>−</td><td>Normales</td></tr>\n          <tr><td><strong>4. Mutant pré-core</strong></td><td><span class=\"kw-chiffre\">&gt; 2000 UI/mL</span></td><td>−</td><td>Élevées</td></tr>\n          <tr><td><strong><span class=\"kw-def\">Hépatite</span> B résolue</strong></td><td>Indétectable</td><td>−</td><td>Normales (apparition des <span class=\"kw-bio\">Ac anti-HBs</span>)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Discriminant majeur :</strong> <span class=\"kw-alerte\">VHB oncogène → CHC sans cirrhose</span> ; <span class=\"kw-clinique\">VHC non oncogène → CHC impossible sans cirrhose</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 279 — <span class=\"kw-def\">Cirrhose</span> · 304 — Tumeur du foie</em></p>","frequence":6},{"id":"167-10","rang":"B","rubrique":"Prise en charge","titre":"Connaître le principe des traitements","contenu":"<p><strong><span class=\"kw-def\">Hépatite</span> aiguë :</strong> le <span class=\"kw-ttt\">repos est l'unique traitement</span>. Éviter l'<span class=\"kw-etio\">alcool</span> et <span class=\"kw-clinique\">les</span> médicaments hépatotoxiques (<span class=\"kw-ci\">paracétamol</span>, <span class=\"kw-ci\">AINS</span>) ainsi que les <span class=\"kw-ci\">sédatifs</span> (majoration des troubles neurologiques) ; surveiller transaminases / <span class=\"kw-bio\">bilirubine</span> / <span class=\"kw-bio\">TP</span>. <strong>Pas de plasma frais congelé systématique</strong> — uniquement en cas de syndrome <span class=\"kw-etio\">hémorragique</span> clinique.</p>\n      <p><span class=\"kw-ttt\">N-acétylcystéine IV</span> : à la <strong>moindre suspicion</strong> d'intoxication au <span class=\"kw-ttt\">paracétamol</span>, quel que soit le résultat de la paracétamolémie ; proposée <strong>systématiquement</strong> en cas d'IHA sévère, quelle que soit la cause suspectée.</p>\n      <p>Un traitement <span class=\"kw-ttt\">antiviral</span> en milieu spécialisé est indiqué dans deux situations :</p>\n      <ul>\n        <li><strong><span class=\"kw-def\">Hépatite</span> C aiguë</strong> : <span class=\"kw-ttt\">sofosbuvir + velpatasvir</span> ou <span class=\"kw-ttt\">glécaprévir + pibrentasvir</span>.</li>\n        <li><strong><span class=\"kw-def\">Hépatite</span> B aiguë grave</strong> : <span class=\"kw-ttt\">ténofovir</span> ou <span class=\"kw-ttt\">entécavir</span>.</li>\n      </ul>\n      <table >\n        <thead><tr><th><span class=\"kw-def\">Hépatite</span> chronique</th><th>Principe du traitement</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-etio\">VHB</span></strong></td><td>But = <span class=\"kw-def\">contrôler la réplication virale</span>. Traitement <strong>suspensif, non curatif</strong> (ADN intégré au noyau). Analogues nucléos(t)idiques au long cours (<span class=\"kw-ttt\">entécavir</span>, <span class=\"kw-ttt\">ténofovir</span>) ou <span class=\"kw-ttt\">interféron pégylé</span> à durée fixe.</td></tr>\n          <tr><td><strong><span class=\"kw-etio\">VHC</span></strong></td><td><span class=\"kw-ttt\">AAD pangénotypiques</span> (anti-NS5B / NS5A / NS3-4A) chez <strong>tous</strong> <span class=\"kw-clinique\">les</span> patients ARN <span class=\"kw-etio\">VHC</span>+, durée <span class=\"kw-chiffre\">8-12 semaines</span> ; RVS <span class=\"kw-chiffre\">&gt; 95 %</span> = guérison.</td></tr>\n          <tr><td><strong><span class=\"kw-etio\">VHD</span></strong></td><td>Nouveaux antiviraux (<span class=\"kw-ttt\">bulévirtide</span>) ayant récemment obtenu l'AMM pour l'<span class=\"kw-def\">hépatite</span> chronique delta.</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Indications du traitement du <span class=\"kw-etio\">VHB</span> chronique :</strong> ADN <span class=\"kw-etio\">VHB</span> &gt; <span class=\"kw-chiffre\">2000 UI</span>/mL + transaminases élevées ou activité ≥ A2 ou fibrose ≥ F2 ; <span class=\"kw-def\">cirrhose</span> dès que l'ADN est détectable ; manifestation extra-hépatique ; ATCD familial de CHC ; avant un traitement <span class=\"kw-ttt\">immunosuppresseur</span>.</p>\n      <div class=\"callout callout-info\"><strong>À retenir :</strong> la guérison du <span class=\"kw-etio\">VHC</span> (RVS) <strong>ne confère pas d'immunité</strong> contre une réinfection, et le <span class=\"kw-def\">dépistage</span> du CHC doit être <strong>poursuivi</strong>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 279 — <span class=\"kw-def\">Cirrhose</span></em></p>","frequence":0},{"id":"167-11","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principales indications des vaccins contre l’hépatite A et l’hépatite B","contenu":"<p>Deux vaccins sont au programme. Le vaccin <span class=\"kw-etio\">VHB</span> protège aussi contre le <span class=\"kw-etio\">VHD</span> (pas d'infection delta sans <span class=\"kw-etio\">VHB</span>).</p>\n      <table >\n        <thead><tr><th></th><th>Vaccin <span class=\"kw-etio\">VHA</span></th><th>Vaccin VHB</th></tr></thead>\n        <tbody>\n          <tr><td>Type</td><td>Vaccin <span class=\"kw-def\">inactivé</span></td><td>Vaccin <span class=\"kw-def\">protéique inactivé</span></td></tr>\n          <tr><td>Schéma</td><td>Dès <span class=\"kw-chiffre\">≥ 1 an</span> ; 2 doses (<span class=\"kw-chiffre\">M0, M6-M12</span>) ; protection <span class=\"kw-chiffre\">95 %</span></td><td>Nourrisson : hexavalent <span class=\"kw-ttt\">DTCaP</span>-Hib-<span class=\"kw-etio\">VHB</span> à <span class=\"kw-chiffre\">M2, M4, rappel M11</span>. Enfant / adulte : <span class=\"kw-chiffre\">M0, M1, M6</span> ; rattrapage jusqu'à<span class=\"kw-chiffre\"> 15 ans</span> révolus (<span class=\"kw-chiffre\">11-15 ans</span> : 2 doses <span class=\"kw-chiffre\">M0, M6</span>)</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Indications du vaccin <span class=\"kw-etio\">VHA</span> :</strong></p>\n      <ul>\n        <li><strong>Pré-exposition :</strong> hépatopathie chronique / <span class=\"kw-def\">cirrhose</span> / co-infection <span class=\"kw-etio\">VHB</span>-<span class=\"kw-etio\">VHC</span> ; <span class=\"kw-clinique\">HSH</span> ; voyageurs en zone d'endémie ; enfants dont un parent vient d'un pays de forte endémie ; militaires ; professionnels (petite enfance, structures handicap, eaux usées, restauration collective).</li>\n        <li><strong>Post-exposition :</strong> <span class=\"kw-def\">contact</span> avec un cas dans un délai <span class=\"kw-chiffre\">≤ 14 jours</span>.</li>\n      </ul>\n      <p><strong>Indications du vaccin <span class=\"kw-etio\">VHB</span> :</strong></p>\n      <ul>\n        <li><span class=\"kw-alerte\">Obligatoire pour tous les nourrissons nés depuis 2018</span> ; rattrapage jusqu'à<span class=\"kw-chiffre\"> 15 ans</span> révolus.</li>\n        <li>Professionnels de santé : <span class=\"kw-ttt\">vaccination</span> <strong>obl<span class=\"kw-chiffre\">iga</span>toire</strong>.</li>\n        <li>Sujets à risque : <span class=\"kw-clinique\">VIH / VHC</span>, dialysés, toxicomanes IV, partenaires multiples, entourage d'un porteur AgHBs+, détenus.</li>\n        <li>Post-exposition de l'entourage : <span class=\"kw-chiffre\">J0-J7-J21 + rappel M12</span>.</li>\n        <li>Nouveau-né de mère AgHBs+ : <span class=\"kw-alerte\">sérovaccination (Ig anti-HBs + 1ʳᵉ dose) avant H12 de vie</span>.</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 146 — <span class=\"kw-ttt\">Vaccination</span></em></p>","frequence":1}],"astuces":[{"type":"danger","titre":"Hépatite fulminante : la triade qui sauve","contenu":"Devant toute hépatite aiguë : <strong>TP + facteur V + recherche d'astérixis</strong> à chaque consultation. <strong>Encéphalopathie + facteur V &lt; 50 %</strong> dans les 2 sem post-ictère = fulminante = appel centre de transplantation <strong>immédiat</strong> (Clichy-Villejuif : facteur V &lt; 20 % si &lt; 30 ans, &lt; 30 % si ≥ 30 ans). Ne jamais attendre."},{"type":"tip","titre":"Sérologie VHB : décodage en 3 questions","contenu":"1) <strong>AgHBs+</strong> ? → infection en cours (aiguë si &lt; 6 mois, chronique si &gt; 6 mois). 2) <strong>Ac anti-HBc+</strong> ? → contact avec le virus (IgM = aigu, IgG = ancien ou chronique). 3) <strong>Ac anti-HBs+</strong> isolé ? → vaccination. <strong>Ac anti-HBs + anti-HBc</strong> : guérison. <strong>AgHBs + anti-HBc IgM</strong> : hépatite B aiguë. <strong>AgHBs + anti-HBc IgG &gt; 6 mois</strong> : hépatite B chronique."},{"type":"warn","titre":"VHE et femme enceinte : ne pas oublier","contenu":"Le <strong>VHE génotype 1</strong> (zones d'endémie : Asie, Afrique) provoque chez la femme enceinte au 3<sup>e</sup> trimestre une <strong>hépatite fulminante avec mortalité jusqu'à 20 %</strong>. Devant toute hépatite aiguë chez une femme enceinte revenant d'un pays d'endémie : IgM anti-VHE en urgence. Le <strong>génotype 3 autochtone</strong> (France, charcuterie de porc) donne plutôt des formes neurologiques (Guillain-Barré, Parsonage-Turner)."},{"type":"info","titre":"AAD pangénotypiques : la révolution VHC","contenu":"Depuis 2017, traitement universel du VHC chronique par <strong>sofosbuvir/velpatasvir 12 sem</strong> ou <strong>glécaprévir/pibrentasvir 8 sem</strong> (sans cirrhose) avec <strong>RVS12 ≥ 95 %</strong> = guérison virologique. Plus d'interféron ni de ribavirine en 1<sup>re</sup> ligne. <strong>Piège</strong> : la guérison virologique n'annule PAS le risque de CHC sur cirrhose → surveillance écho + AFP / 6 mois à vie."},{"type":"tip","titre":"Sérovaccination néonatale VHB : &lt; 12 h","contenu":"Toute femme enceinte AgHBs+ → nouveau-né reçoit dans les <strong>12 h après la naissance</strong> : Ig anti-HBs (200 UI IM) + 1<sup>re</sup> dose de vaccin VHB (sites distincts), puis schéma 3 doses standard. Si charge virale maternelle &gt; 200 000 UI/mL au 3<sup>e</sup> trimestre : ajouter <strong>ténofovir</strong> chez la mère dès la 28<sup>e</sup> SA. Cette sérovaccination ↓ la transmission verticale de 90 % à &lt; 5 %."}],"strategie":{"urgence":"<p><strong>IHA grave / fulminante</strong></p><p><span class=\"kw-def\">contact</span> d'un <span class=\"kw-def\">centre expert</span> sans délai et discussion d'une <span class=\"kw-alerte\">transplantation hépatique en super-urgence</span></p><ul><li><span class=\"kw-alerte\">urgence vitale</span></li></ul><p><strong>Antidote <span class=\"kw-ttt\">paracétamol</span></strong></p><p><span class=\"kw-ttt\">N-acétylcystéine IV</span> à la <em>moindre suspicion</em>, <span class=\"kw-ci\">quel que soit le résultat de la paracétamolémie</span> ; <strong>systématique</strong> si IHA sévère quelle que soit la cause suspectée</p><p><strong><span class=\"kw-def\">Sérovaccination</span> néonatale <span class=\"q\">(mère <span class=\"kw-bio\">AgHBs +</span>)</span></strong></p><p><span class=\"kw-ttt\">Ig anti-HBs</span> + 1ʳᵉ dose vaccin <span class=\"kw-alerte\">avant H12 de vie</span></p><p><strong>Post-exposition <span class=\"kw-etio\">VHA</span></strong></p><p><span class=\"kw-ttt\">vaccination</span> du <span class=\"kw-def\">contact</span> dans un délai <span class=\"kw-chiffre\">≤ 14 jours</span></p><p><strong>Post-exposition <span class=\"kw-etio\">VHB</span></strong></p><p>schéma accéléré <span class=\"kw-chiffre\">J0 – J7 – J21 + rappel M12</span></p>","hospit":"<p><strong>Ambulatoire :</strong> hépatite aiguë <span class=\"kw-etio\">virale</span> <em>bénigne</em> chez l'immunocompétent (<span class=\"kw-bio\">TP &gt; 50 %</span>, pas d'<span class=\"kw-clinique\">encéphalopathie</span>, pas d'<span class=\"kw-clinique\">ictère</span> prolongé) — repos + <span class=\"kw-def\">surveillance</span> bio <span class=\"kw-chiffre\">1×/semaine</span>.<br><strong><span class=\"kw-alerte\">Hospitalisation</span> conventionnelle :</strong> <span class=\"kw-def\">hépatite sévère</span> (<span class=\"kw-alerte\">TP &lt; 50 %</span> ou <span class=\"kw-alerte\">facteur V &lt; 50 %</span>), <span class=\"kw-clinique\">ictère</span> prolongé, <span class=\"kw-def\">terrain</span> fragile (hépatopathie chronique, femme enceinte au 3ᵉ trimestre, enfant).<br><strong><span class=\"kw-alerte\">Réanimation</span> + centre expert :</strong> <span class=\"kw-def\">IHA grave</span> (apparition d'une <span class=\"kw-alerte\">encéphalopathie hépatique</span>) → <span class=\"kw-def\">contact</span> précoce d'un centre de transplantation, discussion <span class=\"kw-alerte\">transplantation hépatique en super-urgence</span>.<br><strong>Avis spécialisé virologie/hépato</strong> : toute <span class=\"kw-def\">hépatite C aiguë</span> (traitement <span class=\"kw-ttt\">antiviral</span>) ; <span class=\"kw-def\">hépatite B aiguë grave</span> (<span class=\"kw-ttt\">ténofovir</span> ou <span class=\"kw-ttt\">entécavir</span>) ; <span class=\"kw-def\">hépatite chronique B / C / D</span> (indication et choix du traitement).</p>","redflags":"<ul><li><span class=\"kw-alerte\">Encéphalopathie hépatique</span> à tous <span class=\"kw-clinique\">les</span> stades : <span class=\"kw-clinique\">astérixis</span> + inversion veille/sommeil (<span class=\"kw-def\">stade</span> 1) → <span class=\"kw-clinique\">confusion</span> (<span class=\"kw-chiffre\">stade 2</span>) → <span class=\"kw-clinique\">coma</span> vigil <span class=\"kw-chiffre\">Glasgow 10-13</span> (<span class=\"kw-chiffre\">stade 3</span>) → <span class=\"kw-clinique\">coma</span> profond <span class=\"kw-chiffre\">Glasgow 3-9</span> (<span class=\"kw-chiffre\">stade 4</span>)</li><li><span class=\"kw-alerte\">TP &lt; 50 %</span> ou <span class=\"kw-alerte\">facteur V &lt; 50 %</span> (= hépatite sévère même sans encéphalopathie)</li><li><span class=\"kw-alerte\">Hypoglycémie</span> (hyperinsulinisme secondaire + ↓ néoglucogenèse)</li><li><span class=\"kw-bio\">Hyperlactatémie</span> (par ↓ <span class=\"kw-bio\">clairance</span> hépatique)</li><li><span class=\"kw-clinique\">Ictère</span> prolongé</li><li><span class=\"kw-alerte\">Syndrome hémorragique</span> clinique</li><li><span class=\"kw-clinique\">Hypotension</span> / <span class=\"kw-clinique\">tachycardie</span> / <span class=\"kw-alerte\">défaillance</span> multiviscérale</li><li><span class=\"kw-clinique\">Hyperventilation</span> précoce (<span class=\"kw-bio\">alcalose respiratoire</span> habituelle)</li><li><span class=\"kw-clinique\">Ascite</span> d'apparition aiguë</li><li><span class=\"kw-alerte\">Femme enceinte au 3ᵉ trimestre</span> + <span class=\"kw-etio\">VHE</span> → forme fulminante <span class=\"kw-chiffre\">≈ 20 %</span> (mort in utero)</li><li><span class=\"kw-alerte\">Hépatopathie chronique préexistante</span> (<span class=\"kw-def\">terrain</span> à risque de forme grave)</li><li><span class=\"kw-alerte\">Sérologie : Ac anti-HBc isolé</span> → suspicion d'infection occulte / fenêtre sérologique à explorer</li></ul>","principes":"<p>Cinq piliers : <span class=\"kw-ttt\">repos</span> = unique traitement de l'hépatite aiguë non sévère ; <span class=\"kw-ci\">éviction</span> des hépatotoxiques et sédatifs ; <span class=\"kw-ttt\">N-acétylcystéine IV</span> si <span class=\"kw-ttt\">paracétamol</span> ou IHA sévère ; <span class=\"kw-ttt\">antiviraux</span> ciblés (<span class=\"kw-etio\">VHB</span> / <span class=\"kw-etio\">VHC</span> / VHD selon situation) ; <span class=\"kw-ttt\">vaccination</span> et mesures de santé publique (<span class=\"kw-def\">DO</span>, entourage).</p><p><strong>Hépatite aiguë non sévère</strong></p><ul><li><span class=\"kw-ttt\">repos</span> = unique traitement. <span class=\"kw-ci\">Éviter</span> <span class=\"kw-etio\">alcool</span>, <span class=\"kw-ci\">paracétamol</span>, <span class=\"kw-ci\">AINS</span> et <span class=\"kw-ci\">sédatifs</span> (majoration des troubles neurologiques). <span class=\"kw-def\">Surveillance</span> bio (<span class=\"kw-bio\">transaminases</span> / <span class=\"kw-bio\">bilirubine</span> / <span class=\"kw-bio\">TP</span>) <span class=\"kw-chiffre\">1×/sem</span> tant que la <span class=\"kw-bio\">bilirubine</span> est élevée.</li></ul><p><strong>Pas de PFC systématique</strong></p><ul><li>uniquement si <span class=\"kw-alerte\">syndrome hémorragique</span> clinique.</li></ul><p><strong>Antidote <span class=\"kw-ttt\">paracétamol</span></strong></p><ul><li><span class=\"kw-ttt\">N-acétylcystéine IV</span> à la moindre suspicion d'intoxication, <span class=\"kw-ci\">quel que soit le résultat de la paracétamolémie</span></li><li><strong>systématique</strong> en cas d'IHA sévère quelle que soit la cause.</li></ul><p><strong><span class=\"kw-def\">Hépatite C aiguë</span></strong></p><ul><li><span class=\"kw-ttt\">sofosbuvir + velpatasvir</span> ou <span class=\"kw-ttt\">glécaprévir + pibrentasvir</span> (avis spécialisé).</li></ul><p><strong><span class=\"kw-def\">Hépatite B aiguë grave</span></strong></p><ul><li><span class=\"kw-ttt\">ténofovir</span> ou <span class=\"kw-ttt\">entécavir</span>.</li></ul><p><strong><span class=\"kw-def\">Hépatite chronique B</span></strong></p><ul><li>traitement <strong>suspensif, non curatif</strong> (ADN intégré). <span class=\"kw-ttt\">Analogues nucléos(t)idiques</span> au long cours (<span class=\"kw-ttt\">entécavir</span>, <span class=\"kw-ttt\">ténofovir</span>) ou <span class=\"kw-ttt\">interféron pégylé</span> à durée fixe. Indications : <span class=\"kw-bio\">ADN VHB &gt; 2000 UI/mL</span> + transaminases élevées <em>ou</em> activité ≥ A2 <em>ou</em> fibrose ≥ F2 ; <span class=\"kw-def\">cirrhose</span> dès ADN détectable ; manifestation extra-hépatique ; ATCD familial de <span class=\"kw-alerte\">CHC</span> ; avant un traitement <span class=\"kw-ttt\">immunosuppresseur</span>.</li></ul><p><strong><span class=\"kw-def\">Hépatite chronique C</span></strong></p><ul><li><span class=\"kw-ttt\">AAD pangénotypiques</span> (anti-NS5B / NS5A / NS3-4A) chez <strong>tous</strong> <span class=\"kw-clinique\">les</span> patients <span class=\"kw-bio\">ARN VHC +</span>, durée <span class=\"kw-chiffre\">8-12 semaines</span></li><li><span class=\"kw-bio\">RVS &gt; 95 %</span> = guérison.</li></ul><p><strong><span class=\"kw-def\">Hépatite chronique D</span></strong></p><ul><li><span class=\"kw-ttt\">bulévirtide</span> (nouvel <span class=\"kw-ttt\">antiviral</span> ayant récemment obtenu l'AMM).</li></ul><p><strong>Mesures préventives associées</strong></p><ul><li>bilan d'<span class=\"kw-bio\">IST</span> si <span class=\"kw-etio\">VHB</span> ou <span class=\"kw-etio\">VHC</span></li><li>mesures d'hygiène si <span class=\"kw-etio\">VHA</span>/VHE</li><li><span class=\"kw-ttt\">vaccination</span> de l'entourage si <span class=\"kw-etio\">VHA</span> ou <span class=\"kw-etio\">VHB</span></li><li><span class=\"kw-alerte\">déclaration obligatoire</span> : <span class=\"kw-etio\">VHA</span> aiguë + <span class=\"kw-etio\">VHB</span> aiguë symptomatique.</li></ul>","suivi":"<p><strong>Hépatite aiguë :</strong> <span class=\"kw-bio\">transaminases</span> / <span class=\"kw-bio\">bilirubine</span> / <span class=\"kw-bio\">TP</span> <span class=\"kw-chiffre\">1×/sem</span> tant que la <span class=\"kw-bio\">bilirubine</span> est élevée ; en <span class=\"kw-alerte\">réanimation</span> : <span class=\"kw-bio\">glycémie</span> capillaire, <span class=\"kw-bio\">TP</span>/<span class=\"kw-bio\">facteur V</span>, <span class=\"kw-bio\">lactate</span>.<br><strong><span class=\"kw-etio\">VHC</span> chronique sous AAD :</strong> évaluation de la <span class=\"kw-bio\">RVS</span> (ARN indétectable) à <span class=\"kw-chiffre\">12 semaines</span> après la fin du traitement ; la guérison <span class=\"kw-ci\">ne confère pas d'immunité</span> contre une réinfection.<br><strong>Fibrose :</strong> <span class=\"kw-bio\">FibroTest / FibroMètre / Hépascore</span>, <span class=\"kw-imagerie\">Fibroscan</span>, ou <span class=\"kw-def\">score</span> histologique <span class=\"kw-def\">METAVIR</span> après <span class=\"kw-imagerie\">PBH</span> (<span class=\"kw-ci\">PBH non recommandée</span> si <span class=\"kw-etio\">VHC</span> chronique sans <span class=\"kw-def\">comorbidité</span>).<br><strong><span class=\"kw-def\">Dépistage</span> du CHC :</strong> <span class=\"kw-imagerie\">échographie hépatique</span> tous <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">6 mois si cirrhose</span> ; tous les <span class=\"kw-chiffre\">2 ans si hépatite chronique sans cirrhose</span> ; <span class=\"kw-imagerie\">IRM hépatique</span> pour confirmation.<br><strong>Dépistage VO :</strong> <span class=\"kw-imagerie\">FOGD</span> à la recherche de varices œsogastriques chez le cirrhotique.<br><strong><span class=\"kw-ttt\">Vaccination</span> de l'entourage</strong> systématique si <span class=\"kw-etio\">VHA</span> ou <span class=\"kw-etio\">VHB</span> ; <span class=\"kw-def\">sérovaccination</span> du nouveau-né si mère <span class=\"kw-bio\">AgHBs +</span> (<span class=\"kw-alerte\">avant H12</span>).<br><strong>Déclaration obl<span class=\"kw-chiffre\">iga</span>toire :</strong> <span class=\"kw-alerte\">hépatite A aiguë</span> + <span class=\"kw-alerte\">hépatite B aiguë symptomatique</span>.</p>"},"liensGlobaux":[{"href":"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/ecn-2020-167-web.pdf","label":"Collège Pilly — Hépatites virales (item 167, PDF 2020)"},{"href":"https://www.ce-mir.fr/sites/www.ce-mir.fr/files/medias/documents/53.%20Insuffisance%20h%C3%A9patique%20aigu%C3%AB.pdf","label":"Collège CE-MIR — Insuffisance hépatique aiguë (PDF)"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Hépatite aiguë confirmée — Transaminases > 10 N sur foie antérieurement sain (terme réservé)","detail":"<h4>CAT — Hépatite aiguë & <span class=\"kw-ci\">insuffisance hépatique</span> aiguë — Stratification de la gravité et orientation</h4>","branches":[{"to":"q-encephalo","label":"Encéphalopathie hépatique ?","color":"red"}]},{"id":"q-encephalo","kind":"decision","label":"Présence d'une encéphalopathie hépatique ? — Astérixis · inversion veille/sommeil · confusion · coma (stade 1 à 4)","branches":[{"to":"q-delai","label":"OUI — IHA grave","color":"red"},{"to":"q-severite","label":"NON","color":"amber"}]},{"id":"q-delai","kind":"decision","label":"Délai entre apparition de l'ictère et de l'encéphalopathie ? — Définit fulminante vs subfulminante","branches":[{"to":"t-fulminante","label":"< 15 jours","color":"red"},{"to":"t-subfulminante","label":"15 j – 3 mois","color":"red"}]},{"id":"t-fulminante","kind":"terminal","label":"Hépatite fulminante","color":"red","detail":"<h4>Définition</h4><ul><li>IHA grave avec apparition de l'encéphalopathie < 15 jours après l'ictère, sur foie antérieurement sain</li></ul><h4>Conduite</h4><ul><li><span class=\"kw-def\">Contact</span> <span class=\"kw-def\">centre expert de transplantation</span> SANS DÉLAI</li><li>Discussion d'une <span class=\"kw-alerte\">transplantation hépatique en super-urgence</span></li><li><span class=\"kw-alerte\">Réanimation</span> : scope, VVP, correction hypovolémie (cristalloïdes), <span class=\"kw-def\">surveillance</span> neuro / <span class=\"kw-bio\">glycémie</span> capillaire / <span class=\"kw-bio\">TP</span>-<span class=\"kw-bio\">facteur V</span> / <span class=\"kw-bio\">lactate</span></li><li><span class=\"kw-ttt\">N-acétylcystéine IV</span> <strong>systématique</strong> (bénéfice montré quelle que soit la cause)</li><li>Étiologique : <span class=\"kw-ttt\">ténofovir</span> ou <span class=\"kw-ttt\">entécavir</span> si <span class=\"kw-etio\">VHB</span> ; <span class=\"kw-ttt\">aciclovir IV</span> si <span class=\"kw-etio\">HSV</span> ; désobstruction si Budd-Chiari</li></ul><h4>À éviter</h4><ul><li><span class=\"kw-ci\">Paracétamol</span>, <span class=\"kw-ci\">AINS</span> (hépatotoxiques)</li><li><span class=\"kw-ci\">Sédatifs</span> ou tout traitement à effet sédatif (majoration troubles neurologiques)</li><li><span class=\"kw-ci\">PFC systématique</span> — uniquement si <span class=\"kw-clinique\">syndrome <span class=\"kw-etio\">hémorragique</span></span> clinique</li></ul><h4>Piège</h4><ul><li>Le <span class=\"kw-clinique\">VHC</span> ne donne <strong>quasiment jamais</strong> d'<span class=\"kw-alerte\">hépatite fulminante</span> — chercher <span class=\"kw-etio\">VHA</span>, <span class=\"kw-etio\">VHB</span>, <span class=\"kw-etio\">VHE</span> ou cause <span class=\"kw-etio\">toxique</span> en priorité</li></ul><h4>Renvoi</h4><ul><li>Item 279 — Cirrhose (à distinguer de l'IHA-sur-chronique)</li></ul>"},{"id":"t-subfulminante","kind":"terminal","label":"Hépatite subfulminante","color":"red","detail":"<h4>Définition</h4><ul><li>IHA grave avec apparition de l'encéphalopathie entre <span class=\"kw-chiffre\">15 jours</span> et <span class=\"kw-chiffre\">3 mois</span> après l'<span class=\"kw-clinique\">ictère</span></li></ul><h4>Conduite</h4><ul><li>Identique à la fulminante : <span class=\"kw-def\">centre expert</span> + discussion <span class=\"kw-alerte\">transplantation hépatique en super-urgence</span></li><li><span class=\"kw-ttt\">N-acétylcystéine IV</span> systématique</li><li>Antiviraux ciblés selon étiologie (<span class=\"kw-ttt\">ténofovir</span> si <span class=\"kw-etio\">VHB</span> grave)</li></ul><h4><span class=\"kw-def\">Pronostic</span></h4><ul><li>Mauvais <span class=\"kw-def\">pronostic</span> : <span class=\"kw-etio\">VHB</span>, absence de diagnostic étiologique. Bon pronostic : <span class=\"kw-ttt\">paracétamol</span> et <span class=\"kw-etio\">VHA</span></li></ul>"},{"id":"q-severite","kind":"decision","label":"<span class=\"kw-bio\">TP</span> < <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>50</span> %</span> OU <span class=\"kw-bio\">facteur V</span> < 50 % OU <span class=\"kw-clinique\">ictère</span> prolongé ? — Critères d'hépatite sévère (sans encéphalopathie)","branches":[{"to":"t-severe","label":"OUI — sévère","color":"amber"},{"to":"q-etio","label":"NON","color":"green"}]},{"id":"t-severe","kind":"terminal","label":"Hépatite aiguë sévère (sans encéphalopathie)","color":"amber","detail":"<h4>Définition</h4><ul><li><span class=\"kw-bio\">TP &lt; 50 %</span> ou <span class=\"kw-bio\">facteur V &lt; 50 %</span> en l'absence d'encéphalopathie — ou <span class=\"kw-clinique\">ictère</span> prolongé</li></ul><h4>Conduite</h4><ul><li><span class=\"kw-alerte\">Hospitalisation</span> en milieu spécialisé</li><li><span class=\"kw-def\">Contact</span> préventif d'un centre expert (anticiper une éventuelle aggravation)</li><li><span class=\"kw-def\">Surveillance</span> rapprochée : <span class=\"kw-bio\">TP</span>/<span class=\"kw-bio\">facteur V</span>, <span class=\"kw-bio\">glycémie</span> capillaire, <span class=\"kw-bio\">lactate</span>, état neurologique</li><li><span class=\"kw-ttt\">N-acétylcystéine IV</span> systématique (bénéfice montré quelle que soit la cause d'IHA sévère)</li><li>Si <span class=\"kw-etio\">VHB</span> : <span class=\"kw-ttt\">ténofovir</span> ou <span class=\"kw-ttt\">entécavir</span> ; si <span class=\"kw-etio\">VHC</span> aiguë : <span class=\"kw-ttt\">sofosbuvir + velpatasvir</span> ou <span class=\"kw-ttt\">glécaprévir + pibrentasvir</span></li></ul><h4>À éviter</h4><ul><li><span class=\"kw-ci\">Paracétamol</span>, <span class=\"kw-ci\">AINS</span>, <span class=\"kw-ci\">sédatifs</span>, <span class=\"kw-ci\">PFC systématique</span></li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li>Risque de progression vers IHA grave/fulminante — réévaluer la conscience plusieurs fois par jour</li></ul>"},{"id":"q-etio","kind":"decision","label":"Étiologie identifiée par le bilan de 1ʳᵉ intention ? — IgM VHA · AgHBs + IgM HBc · Ac VHC ± ARN VHC · IgM VHE · paracétamolémie · échographie","branches":[{"to":"t-paracetamol","label":"Toxique : paracétamol (nomogramme Rumack-Matthew)","color":"red"},{"to":"t-virale-benigne","label":"Virale identifiée (VHA / VHB / VHC / VHE)","color":"green"}]},{"id":"t-paracetamol","kind":"terminal","label":"Intoxication au paracétamol","color":"red","detail":"<h4>Clinique</h4><ul><li>Symptômes d'IHA surviennent classiquement après <span class=\"kw-chiffre\">24 h</span> ; toxicité directe ou indirecte (immuno-<span class=\"kw-etio\">allergique</span>)</li></ul><h4>Biologie</h4><ul><li><span class=\"kw-ttt\">Paracétamolémie</span> interprétée selon le délai de la prise (<span class=\"kw-def\">nomogramme de Rumack-Matthew</span>) — <span class=\"kw-ci\">une paracétamolémie nulle n'élimine PAS l'intoxication</span> si dosage tardif</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">N-acétylcystéine IV</span> en <span class=\"kw-alerte\">urgence</span> à la moindre suspicion, <span class=\"kw-ci\">quel que soit le résultat de la paracétamolémie</span></li><li><span class=\"kw-def\">Surveillance</span> hospitalière des paramètres vitaux + <span class=\"kw-bio\">TP</span> / <span class=\"kw-bio\">facteur V</span> / <span class=\"kw-bio\">glycémie</span> / <span class=\"kw-bio\">lactate</span></li></ul><h4>Délai</h4><ul><li>NAC d'autant plus efficace qu'elle est précoce → ne JAMAIS attendre la paracétamolémie pour démarrer</li></ul>"},{"id":"t-virale-benigne","kind":"terminal","label":"Hépatite aiguë virale bénigne","color":"green","detail":"<h4>Clinique</h4><ul><li>Asymptomatique le plus souvent ; sinon triade de Caroli (<span class=\"kw-clinique\">Céphalée</span> / Arthralgie / Rash) en phase pré-ictérique, puis <span class=\"kw-clinique\">ictère</span> cutanéo-muqueux + urines foncées + selles décolorées</li></ul><h4>Conduite</h4><ul><li>Ambulatoire ; <span class=\"kw-ttt\">repos</span> = unique traitement</li><li><span class=\"kw-ci\">Éviction</span> <span class=\"kw-etio\">alcool</span>, <span class=\"kw-ttt\">paracétamol</span>, <span class=\"kw-ttt\">AINS</span>, sédatifs</li><li><span class=\"kw-def\">Surveillance</span> bio (<span class=\"kw-bio\">transaminases</span> / <span class=\"kw-bio\">bilirubine</span> / <span class=\"kw-bio\">TP</span>) <span class=\"kw-chiffre\">1×/semaine</span> tant que <span class=\"kw-bio\">bilirubine</span> élevée</li><li><span class=\"kw-alerte\">Déclaration obligatoire</span> si <span class=\"kw-etio\">VHA</span> aiguë ou <span class=\"kw-etio\">VHB</span> aiguë symptomatique</li></ul><h4>Traitement <span class=\"kw-ttt\">antiviral</span></h4><ul><li><span class=\"kw-etio\">VHC</span> aiguë : <span class=\"kw-ttt\">sofosbuvir + velpatasvir</span> ou <span class=\"kw-ttt\">glécaprévir + pibrentasvir</span> (avis spécialisé)</li><li><span class=\"kw-etio\">VHB</span> : pas de traitement en aigu non grave (<span class=\"kw-def\">suivi</span> sérologique de la chronicisation)</li><li><span class=\"kw-etio\">VHA</span> / VHE : pas de traitement <span class=\"kw-ttt\">antiviral</span> spécifique</li></ul><h4>Prévention</h4><ul><li>Bilan <span class=\"kw-clinique\">IST</span> si <span class=\"kw-etio\">VHB</span> / <span class=\"kw-etio\">VHC</span></li><li><span class=\"kw-ttt\">Vaccination</span> de l'entourage si <span class=\"kw-etio\">VHA</span> ou <span class=\"kw-etio\">VHB</span></li><li>Mesures d'hygiène si <span class=\"kw-etio\">VHA</span> / VHE</li><li><span class=\"kw-def\">Surveillance</span> de la chronicisation : <span class=\"kw-bio\">AgHBs &gt; 6 mois</span> = <span class=\"kw-etio\">VHB</span> chronique ; <span class=\"kw-bio\">ARN VHC &gt; 6 mois</span> = <span class=\"kw-etio\">VHC</span> chronique</li></ul><h4>Renvois</h4><ul><li>Item 278 — <span class=\"kw-clinique\">Ictère</span> · Item 279 — Cirrhose · Item 304 — Tumeur du foie · Item 146 — <span class=\"kw-ttt\">Vaccination</span></li></ul>"}]},"cards":[{"i":"2f5959ec4797","n":167,"o":"167-1","u":"Définition","t":"Connaître la définition d’une hépatite","q":"Quels sont les pièges de vocabulaire concernant l'élévation des transaminases ?","a":"<p>Il est préférable d'utiliser les termes « <strong>élévation des transaminases</strong> » ou « <strong>hypertransaminasémie</strong> » plutôt que « cytolyse hépatique » car une cholestase peut également entraîner une élévation des transaminases sans nécrose hépatocytaire.</p>"},{"i":"487aff033628","n":167,"o":"167-1","u":"Définition","t":"Connaître la définition d’une hépatite","q":"Comment définit-on l'insuffisance hépatique aiguë (IHA) ?","a":"<p>L'insuffisance hépatique aiguë (IHA) se définit comme une <strong>dysfonction hépatique</strong> évoluant généralement en <strong>moins de 3 mois</strong>, survenant sur un <strong>foie sain</strong>.</p>"},{"i":"81c3a1e7c29f","n":167,"o":"167-1","u":"Définition","t":"Connaître la définition d’une hépatite","q":"Comment définit-on une hépatite ?","a":"<p>Une hépatite est une <strong>inflammation du foie</strong>.</p>"},{"i":"bf42466b6229","n":167,"o":"167-1","u":"Définition","t":"Connaître la définition d’une hépatite","q":"Comment distingue-t-on une hépatite aiguë d'une hépatite chronique en termes de durée et de niveau des transaminases ?","a":"<ul><li>Une <strong>hépatite aiguë</strong> dure généralement <strong>moins de 6 mois</strong>, avec des transaminases souvent <strong>supérieures à 10 N</strong>, survenant sur un foie antérieurement sain.</li><li>Une <strong>hépatite chronique</strong> dure généralement <strong>plus de 6 mois</strong>, avec des transaminases souvent <strong>inférieures à 5 N</strong>.</li></ul>"},{"i":"c4f73246e900","n":167,"o":"167-1","u":"Définition","t":"Connaître la définition d’une hépatite","q":"Quels sont les modes de détection biologique d'une hépatite ?","a":"<ul><li>Une élévation des <strong>transaminases</strong> (ASAT / ALAT) qui traduit une nécrose des hépatocytes.</li><li>Une <strong>cholestase</strong>.</li></ul><p>Une forme mixte cytolytique / cholestatique est également possible.</p>"},{"i":"59aee4a637fb","n":167,"o":"167-11","u":"Prise en charge","t":"Connaître les principales indications des vaccins contre l’hépatite A et l’hépatite B","q":"Quelles sont les principales indications de la vaccination contre l'hépatite B ?","a":"<p>La vaccination contre l'hépatite B est indiquée pour :</p><ul><li>Tous les <strong>nourrissons nés depuis 2018 (vaccination obligatoire)</strong>, avec un programme de rattrapage jusqu'à 15 ans révolus.</li><li>Les <strong>professionnels de santé (vaccination obligatoire)</strong>.</li><li>Les <strong>sujets à risque</strong> tels que les personnes atteintes du <strong>VIH</strong> ou du <strong>VHC</strong>, les <strong>dialysés</strong>, les <strong>toxicomanes IV</strong>, les personnes ayant des <strong>partenaires sexuels multiples</strong>, l'<strong>entourage d'un porteur AgHBs+</strong> et les <strong>détenus</strong>.</li><li>La <strong>sérovaccination</strong> (immunoglobulines anti-HBs + 1ère dose de vaccin) chez le <strong>nouveau-né de mère AgHBs positive</strong>, administrée avant les 12 heures de vie.</li></ul>"},{"i":"bac1174d489b","n":167,"o":"167-11","u":"Prise en charge","t":"Connaître les principales indications des vaccins contre l’hépatite A et l’hépatite B","q":"Dans quel contexte la vaccination post-exposition contre l'hépatite A est-elle recommandée ?","a":"<p>La vaccination post-exposition contre l'hépatite A est recommandée en cas de <strong>contact avec un cas avéré</strong>, à condition que ce contact soit survenu dans un délai <strong>inférieur ou égal à 14 jours</strong>.</p>"},{"i":"d98ecc0e3b40","n":167,"o":"167-11","u":"Prise en charge","t":"Connaître les principales indications des vaccins contre l’hépatite A et l’hépatite B","q":"Quelles sont les principales indications de la vaccination pré-exposition contre l'hépatite A ?","a":"<p>La vaccination pré-exposition contre l'hépatite A est indiquée pour :</p><ul><li>Les sujets présentant une <strong>hépatopathie chronique</strong>, une <strong>cirrhose</strong> ou une <strong>co-infection VHB/VHC</strong>.</li><li>Les <strong>hommes ayant des relations sexuelles avec d'autres hommes (HSH)</strong>.</li><li>Les <strong>voyageurs</strong> se rendant en zone d'endémie.</li><li>Les <strong>enfants</strong> dont un parent est originaire d'un pays de forte endémie.</li><li>Les <strong>militaires</strong>.</li><li>Certains <strong>professionnels</strong> exercant dans la petite enfance, les structures accueillant des personnes handicapées, les milieux exposés aux eaux usées ou la restauration collective.</li></ul>"},{"i":"1e00994f85c9","n":167,"o":"167-2","u":"Epidémiologie","t":"Connaître les modes de transmission et la prévalence mondiale des différentes hépatites virales","q":"Comment différencier les hépatites virales A et E des hépatites B, C et D concernant leur mode de transmission principal ?","a":"<p>Les hépatites virales <strong>A (VHA)</strong> et <strong>E (VHE)</strong> sont principalement transmises par voie <strong>oro-fécale</strong>, tandis que les hépatites <strong>B (VHB)</strong>, <strong>C (VHC)</strong> et <strong>D (VHD)</strong> ne le sont jamais. Ces dernières sont des virus enveloppés, fragiles dans le milieu extérieur.</p>"},{"i":"36390f44e97d","n":167,"o":"167-2","u":"Epidémiologie","t":"Connaître les modes de transmission et la prévalence mondiale des différentes hépatites virales","q":"Quelle est la prévalence mondiale de l'infection chronique par le virus de l'hépatite B (VHB) et par le virus de l'hépatite C (VHC) ?","a":"<ul><li>Pour le <strong>VHB</strong> : environ <strong>250 millions</strong> de porteurs chroniques dans le monde.</li><li>Pour le <strong>VHC</strong> : une prévalence mondiale de l'infection chronique d'environ <strong>3 %</strong> (soit 190 millions de personnes), avec une forte prévalence en Égypte et un gradient Nord-Sud.</li></ul>"},{"i":"73041f231e8b","n":167,"o":"167-2","u":"Epidémiologie","t":"Connaître les modes de transmission et la prévalence mondiale des différentes hépatites virales","q":"Quels sont les modes de transmission spécifiques aux virus des hépatites B, C et D ?","a":"<ul><li><strong>Voie sexuelle :</strong> +++ pour VHB, VHC, VHD.</li><li><strong>Voie parentérale :</strong> +++ pour VHB, VHC, VHD.</li><li><strong>Voie materno-foetale :</strong> +++ pour VHB (avec une augmentation en cas de co-infection VIH pour VHC).</li></ul>"},{"i":"97f7374d2d37","n":167,"o":"167-2","u":"Epidémiologie","t":"Connaître les modes de transmission et la prévalence mondiale des différentes hépatites virales","q":"Quelles mesures de santé publique sont spécifiquement mises en place pour prévenir la transmission des hépatites virales A et E ?","a":"<p>Pour la prévention des hépatites A (VHA) et E (VHE), les mesures incluent la <strong>lutte contre le péril fécal</strong> (hygiène des mains, de l'eau et des aliments) et la <strong>cuisson à cœur du porc, du sanglier et du gibier</strong> pour le VHE.</p>"},{"i":"53f5d8b426c3","n":167,"o":"167-3","u":"Epidémiologie","t":"Connaître les différents virus (A → E)","q":"Quelle est la particularité du virus de l'hépatite A (VHA) en termes de cytopathogénicité ?","a":"<p>Le VHA n'est <strong>pas directement cytopathogène</strong>. Les lésions hépatiques qu'il provoque sont de nature <strong>immuno-médiée</strong> par la réponse du système immunitaire de l'hôte.</p>"},{"i":"6e25c7746a9f","n":167,"o":"167-3","u":"Epidémiologie","t":"Connaître les différents virus (A → E)","q":"Pourquoi l'hépatite D (VHD) est-elle toujours associée à l'hépatite B (VHB) ?","a":"<p>Le VHD est un virus <strong>défectif</strong> dont la réplication <strong>dépend de la présence du VHB</strong>. Il n'y a donc pas d'infection par le VHD possible sans une infection concomitante ou préalable par le VHB.</p>"},{"i":"9086e20de649","n":167,"o":"167-3","u":"Epidémiologie","t":"Connaître les différents virus (A → E)","q":"Quelle est la principale particularité du virus de l'hépatite C (VHC) concernant son action sur les hépatocytes ?","a":"<p>Le VHC est un virus <strong>directement cytopathogène</strong>, c'est-à-dire qu'il endommage directement les hépatocytes. Il est important de noter que sa charge virale n'est cependant pas corrélée au stade de fibrose hépatique.</p>"},{"i":"9d85d65e9480","n":167,"o":"167-3","u":"Epidémiologie","t":"Connaître les différents virus (A → E)","q":"Quel est le mode de transmission principal du virus de l'hépatite E (VHE) ?","a":"<p>Le VHE se transmet principalement par <strong>voie oro-fécale</strong>. C'est également une maladie <strong>zoonotique</strong>, ce qui signifie qu'il peut être transmis de l'animal à l'homme.</p>"},{"i":"a7a80032fd46","n":167,"o":"167-3","u":"Epidémiologie","t":"Connaître les différents virus (A → E)","q":"Quel est le génome du virus de l'hépatite B (VHB) et quelle est sa particularité par rapport aux autres virus hépatotropes ?","a":"<p>Le VHB possède un génome <strong>ADN circulaire double brin</strong>. C'est le <strong>seul virus hépatotrope à ADN</strong>, ce qui le rend potentiellement <strong>oncogène</strong> et capable de provoquer un carcinome hépatocellulaire (CHC) sans cirrhose préalable.</p>"},{"i":"1f6543898cec","n":167,"o":"167-4","u":"Diagnostic positif","t":"Connaître les principales causes d’élévation des transaminases en dehors de l’infection virale","q":"Quelles sont les étiologies à évoquer devant une élévation modérée des transaminases (inférieure à 5-10 N) en l'absence d'infection virale ?","a":"<ul><li>Une <strong>stéato-hépatite alcoolique</strong>.</li><li>Un <strong>syndrome métabolique</strong> (incluant la stéatopathie métabolique).</li><li>Une <strong>hémochromatose</strong>.</li></ul>"},{"i":"3fdbacd4ae30","n":167,"o":"167-4","u":"Diagnostic positif","t":"Connaître les principales causes d’élévation des transaminases en dehors de l’infection virale","q":"Quelles sont les étiologies à évoquer devant une élévation importante des transaminases (supérieure à 10 N) en dehors d'une infection virale ?","a":"<ul><li>Une <strong>hépatite toxique</strong> (paracétamol, amanite phalloïde, drogues illicites, phytothérapie).</li><li>Une <strong>hépatite auto-immune</strong>.</li><li>Une <strong>hépatite hypoxique</strong> (foie de choc, syndrome de Budd-Chiari).</li><li>Une <strong>maladie de Wilson</strong>.</li></ul>"},{"i":"62f328c97228","n":167,"o":"167-4","u":"Diagnostic positif","t":"Connaître les principales causes d’élévation des transaminases en dehors de l’infection virale","q":"Quel est le mécanisme principal expliquant une élévation des transaminases en cas de \"foie de choc\" ou de syndrome de Budd-Chiari ?","a":"<p>Le mécanisme principal est une <strong>mise en pression hépatocytaire</strong> d'origine vasculaire, liée à l'hypoxie hépatique ou à l'obstruction des veines hépatiques.</p>"},{"i":"698f45f4555a","n":167,"o":"167-4","u":"Diagnostic positif","t":"Connaître les principales causes d’élévation des transaminases en dehors de l’infection virale","q":"Quand suspecter une atteinte extra-hépatique devant une élévation des transaminases sans cause virale ?","a":"<p>Une atteinte extra-hépatique doit être suspectée si l'élévation des transaminases <strong>prédomine sur les ASAT</strong> et peut être confirmée par le dosage des <strong>CPK</strong> pour écarter une origine musculaire (rhabdomyolyse).</p>"},{"i":"b735dd2bb3d9","n":167,"o":"167-4","u":"Diagnostic positif","t":"Connaître les principales causes d’élévation des transaminases en dehors de l’infection virale","q":"Quelle amplitude d'élévation des transaminases doit faire suspecter une étiologie hépatique modérée non virale ?","a":"<p>Une élévation <strong>modérée</strong> des transaminases est généralement inférieure à <strong>5 à 10 fois la normale</strong>.</p>"},{"i":"0d76e3b2df80","n":167,"o":"167-5","u":"Examens complémentaires","t":"Connaître les examens biologiques de première intention devant une hépatite aiguë","q":"Quel examen d'imagerie est recommandé en première intention devant une hépatite aiguë, et que permet-il d'évaluer ?","a":"Une <strong>échographie hépatique</strong> est recommandée en première intention. Elle permet de rechercher notamment :\n<ul>\n<li>Une <strong>migration lithiasique</strong> (cause de cholestase obstructive).</li>\n<li>Des signes de <strong>maladie chronique du foie</strong> préexistante.</li>\n<li>Une <strong>thrombose des veines hépatiques</strong> (syndrome de Budd-Chiari) ou de la <strong>veine porte</strong>.</li>\n</ul>"},{"i":"c0a333adab37","n":167,"o":"167-5","u":"Examens complémentaires","t":"Connaître les examens biologiques de première intention devant une hépatite aiguë","q":"Dans quels cas doit-on rechercher une surinfection delta en présence d'une hépatite B aiguë ?","a":"En cas de positivité de l'AgHBs (signant une infection par le VHB), il convient de rechercher une éventuelle surinfection delta par la recherche des <strong>IgM anti-delta</strong> et de l'<strong>ARN delta</strong>."},{"i":"f4cde9ef57f3","n":167,"o":"167-5","u":"Examens complémentaires","t":"Connaître les examens biologiques de première intention devant une hépatite aiguë","q":"Quels sont les examens biologiques sérologiques de première intention à réaliser devant une hépatite aiguë pour identifier l'agent viral ?","a":"Devant une hépatite aiguë, les examens biologiques de première intention incluent :\n<ul>\n<li>Recherche d'<strong>IgM anti-VHA</strong> pour une infection aiguë par le virus de l'hépatite A.</li>\n<li>Recherche d'<strong>anticorps anti-VHC</strong> (Ac anti-VHC) et, si positifs, d'<strong>ARN VHC</strong> pour une infection aiguë par le virus de l'hépatite C.</li>\n<li>Recherche de l'<strong>AgHBs</strong> pour une infection par le virus de l'hépatite B. Si positif, compléter par les <strong>IgM anti-HBc</strong> et l'<strong>ADN VHB</strong>.</li>\n<li>Recherche des <strong>IgM anti-VHE</strong> pour une infection aiguë par le virus de l'hépatite E.</li>\n</ul>"},{"i":"fed6b0f379d1","n":167,"o":"167-5","u":"Examens complémentaires","t":"Connaître les examens biologiques de première intention devant une hépatite aiguë","q":"Quels dépistages toxicologiques sont à envisager en première intention devant une hépatite aiguë ?","a":"Les dépistages toxicologiques de première intention devant une hépatite aiguë incluent :\n<ul>\n<li>L'<strong>alcoolémie</strong>.</li>\n<li>La recherche urinaire de <strong>cocaïne</strong> ou d'<strong>amphétamines</strong>.</li>\n<li>La <strong>paracétamolémie</strong>, qui doit être interprétée selon le délai de la prise à l'aide du nomogramme de <strong>Rumack et Matthew</strong>. Il est important de noter qu'une paracétamolémie nulle n'élimine pas une intoxication si le dosage est réalisé tardivement.</li>\n</ul>"},{"i":"2b5250c51bda","n":167,"o":"167-6","u":"Examens complémentaires","t":"Connaître les examens biologiques de première intention devant une hépatite chronique","q":"Dans le contexte d'une hépatite chronique, quel est le protocole de dépistage du carcinome hépatocellulaire (CHC) ?","a":"<p>Le dépistage du carcinome hépatocellulaire (CHC) repose sur :</p><ul><li>Une <strong>échographie hépatique</strong> (pour le dépistage) tous les <strong>6 mois en cas de cirrhose</strong>, et tous les <strong>2 ans en cas d'hépatite chronique sans cirrhose</strong>.</li><li>Une <strong>IRM hépatique</strong> (pour la confirmation si nécessaire).</li><li>Une <strong>Fibroscopie Oeso-Gastro-Duodénale (FOGD)</strong> est également réalisée à la recherche de varices œsophagiennes.</li></ul>"},{"i":"8c0134d01a70","n":167,"o":"167-6","u":"Examens complémentaires","t":"Connaître les examens biologiques de première intention devant une hépatite chronique","q":"Quels sont les items clés du bilan biologique de première intention commun aux hépatites chroniques B et C ?","a":"<p>Les examens biologiques de première intention communs aux hépatites chroniques B et C comprennent :</p><ul><li>Un <strong>bilan hépatique</strong> (transaminases, GGT, PAL).</li><li>La <strong>NFS</strong>.</li><li>L'<strong>albuminémie</strong>.</li><li>L'<strong>hémostase</strong> : TP, facteur V (si TP &lt; 70%), INR (si cirrhose pour le score MELD).</li><li>Une <strong>sérologie VIH</strong> (en raison de la co-infection fréquente).</li></ul>"},{"i":"bf0f4ec8af9c","n":167,"o":"167-6","u":"Examens complémentaires","t":"Connaître les examens biologiques de première intention devant une hépatite chronique","q":"Quelles sont les méthodes d'évaluation de la fibrose hépatique dans le bilan de première intention d'une hépatite chronique ?","a":"<p>L'évaluation de la fibrose hépatique peut être réalisée par :</p><ul><li>Des <strong>marqueurs sériques indirects</strong> (FibroTest, FibroMètre, Hépascore).</li><li>L'<strong>élastométrie hépatique</strong> (FibroScan).</li><li>Un <strong>score histologique METAVIR</strong> (après Ponction Biopsie Hépatique), qui évalue l'activité (A0-A3) et la fibrose (F0-F4). La <strong>PBH n'est pas recommandée</strong> si l'hépatite C chronique est isolée sans comorbidité.</li></ul>"},{"i":"e0427abdb72e","n":167,"o":"167-6","u":"Examens complémentaires","t":"Connaître les examens biologiques de première intention devant une hépatite chronique","q":"Comment confirme-t-on biologiquement une hépatite chronique virale B et C ?","a":"<p>Une hépatite chronique virale est confirmée par la persistance des anomalies pendant <strong>plus de 6 mois</strong> :</p><ul><li>Pour le VHB : <strong>AgHBs positif</strong>.</li><li>Pour le VHC : <strong>ARN VHC positif</strong>.</li></ul>"},{"i":"176c650949e0","n":167,"o":"167-8","u":"Identifier une urgence","t":"Connaître les signes de gravité d’une hépatite aiguë","q":"Comment définit-on une hépatite aiguë « sévère » selon les critères de gravité ?","a":"<p>Une hépatite aiguë est définie comme « sévère » en présence de :</p><ul><li>Un <strong>TP &lt; 50 %</strong> ou un <strong>facteur V &lt; 50 %</strong>, en l'absence d'encéphalopathie hépatique.</li><li>Ou un <strong>ictère prolongé</strong>.</li></ul>"},{"i":"19c6a27d7213","n":167,"o":"167-8","u":"Identifier une urgence","t":"Connaître les signes de gravité d’une hépatite aiguë","q":"Quels sont les stades de l'encéphalopathie hépatique et leurs principales manifestations ?","a":"<p>L'encéphalopathie hépatique est classée en plusieurs stades :</p><ul><li><strong>Stade 1</strong> : <strong>Astérixis</strong> et altération du cycle veille/sommeil.</li><li><strong>Stade 2</strong> : <strong>Confusion</strong>.</li><li><strong>Stade 3</strong> : <strong>Coma vigil</strong> (Glasgow 10-13).</li><li><strong>Stade 4</strong> : <strong>Coma profond</strong> (Glasgow 3-9).</li></ul>"},{"i":"3f6ae3ff71bc","n":167,"o":"167-8","u":"Identifier une urgence","t":"Connaître les signes de gravité d’une hépatite aiguë","q":"Comment définit-on une hépatite aiguë « grave » ou « fulminante » ?","a":"<p>Une hépatite aiguë est qualifiée de « grave » ou « fulminante » par l'apparition d'une <strong>encéphalopathie hépatique</strong>.</p><ul><li>Elle est dite <strong>fulminante</strong> si l'encéphalopathie apparaît <strong>&lt; 15 jours</strong> après l'ictère.</li><li>Elle est dite <strong>subfulminante</strong> si l'encéphalopathie apparaît entre <strong>15 jours et 3 mois</strong>.</li></ul>"},{"i":"47b8b5c83cb3","n":167,"o":"167-8","u":"Identifier une urgence","t":"Connaître les signes de gravité d’une hépatite aiguë","q":"Outre l'encéphalopathie et l'altération du bilan de coagulation, quels sont les autres signes de gravité d'une hépatite aiguë ?","a":"<p>Les autres signes de gravité d'une hépatite aiguë incluent :</p><ul><li><strong>Hypoglycémie</strong> (due à un hyperinsulinisme secondaire et une diminution de la néoglucogenèse).</li><li><strong>Hyperlactatémie</strong>.</li><li><strong>Ascite</strong>.</li><li><strong>Syndrome hémorragique</strong>.</li><li><strong>Hypotension</strong> / <strong>tachycardie</strong> / défaillance multiviscérale.</li><li><strong>Hyperventilation précoce</strong> avec alcalose respiratoire habituelle.</li></ul>"},{"i":"71bd9d531f6a","n":167,"o":"167-8","u":"Identifier une urgence","t":"Connaître les signes de gravité d’une hépatite aiguë","q":"Quels sont les terrains à risque de développer une forme grave d'hépatite aiguë ?","a":"<p>Les terrains à risque de développer une forme grave d'hépatite aiguë sont :</p><ul><li>La <strong>femme enceinte au 3ème trimestre</strong>, notamment en cas d'infection par le virus de l'hépatite E (VHE) avec un risque d'hépatite fulminante d'environ 20 % et de mort in utero.</li><li>L'<strong>enfant</strong>.</li><li>Une <strong>hépatopathie chronique préexistante</strong>.</li></ul>"},{"i":"d8486fffe5d3","n":167,"o":"167-8","u":"Identifier une urgence","t":"Connaître les signes de gravité d’une hépatite aiguë","q":"Quelle est la conduite à tenir en urgence devant une hépatite aiguë grave ou fulminante ?","a":"<p>Devant une hépatite aiguë grave ou fulminante, il s'agit d'une urgence nécessitant :</p><ul><li>Un <strong>contact précoce avec un centre expert</strong>.</li><li>Une discussion rapide pour une <strong>transplantation hépatique en super-urgence</strong>.</li></ul>"},{"i":"28632c5b61d5","n":167,"o":"167-9","u":"Suivi et/ou pronostic","t":"Connaître le mode évolutif des hépatites virales","q":"Quelles sont les phases évolutives de l'hépatite B chronique en se basant sur les marqueurs virologiques et biologiques ?","a":"<ul><li><strong>1. Tolérance immunitaire</strong> : ADN VHB > 8 log UI/mL, AgHBe présent, transaminases normales.</li><li><strong>2. Clairance immunitaire</strong> : ADN VHB < 8 log UI/mL, AgHBe présent, transaminases élevées.</li><li><strong>3. Portage inactif</strong> : ADN VHB < 2000 UI/mL, AgHBe absent, transaminases normales.</li><li><strong>4. Mutant pré-core</strong> : ADN VHB > 2000 UI/mL, AgHBe absent, transaminases élevées.</li></ul><p>Une <strong>hépatite B résolue</strong> correspond à un ADN VHB indétectable, l'AgHBe absent, des transaminases normales, et l'apparition des Ac anti-HBs.</p>"},{"i":"39a04408eb77","n":167,"o":"167-9","u":"Suivi et/ou pronostic","t":"Connaître le mode évolutif des hépatites virales","q":"Quel est le devenir évolutif du VHA et du VHE chez un patient non immunodéprimé ?","a":"<p>Pour le <strong>VHA</strong>, l'évolution est toujours une <strong>guérison spontanée</strong>, sans risque de chronicité, de cirrhose ou de carcinome hépatocellulaire (CHC).</p><p>Pour le <strong>VHE</strong>, chez un sujet immunocompétent, l'évolution est également vers la guérison spontanée. Le risque de chronicité n'existe que chez l'<strong>immunodéprimé</strong>.</p>"},{"i":"435e64d52f97","n":167,"o":"167-9","u":"Suivi et/ou pronostic","t":"Connaître le mode évolutif des hépatites virales","q":"Comment la co-infection ou la surinfection par le VHD modifie-t-elle le pronostic de l'hépatite B ?","a":"<ul><li><strong>Co-infection VHB + VHD (simultanée)</strong> : elle évolue quasi systématiquement vers la <strong>guérison</strong>.</li><li><strong>Surinfection VHD d'un porteur VHB chronique</strong> : elle évolue vers une <strong>hépatite chronique D</strong>, ce qui <strong>augmente significativement le risque de cirrhose et de CHC</strong> lié au VHB.</li></ul>"},{"i":"67c58165f9eb","n":167,"o":"167-9","u":"Suivi et/ou pronostic","t":"Connaître le mode évolutif des hépatites virales","q":"Quels sont les pourcentages de chronicité, de cirrhose et de carcinome hépatocellulaire (CHC) associés aux hépatites B et C ?","a":"<ul><li><strong>Hépatite B (VHB)</strong> :</li><ul><li>Chronicité : <strong>5-10 %</strong></li><li>Cirrhose : <strong>10-20 %</strong></li><li>CHC : <strong>3-5 %/an même sans cirrhose</strong> (le VHB est oncogène).</li></ul><li><strong>Hépatite C (VHC)</strong> :</li><ul><li>Chronicité : <strong>65-85 %</strong></li><li>Cirrhose : <strong>10-20 %</strong></li><li>CHC : <strong>3-5 %/an, mais seulement après cirrhose</strong> (le VHC n'est pas oncogène directement).</li></ul></ul>"},{"i":"e0696d95993f","n":167,"o":"167-9","u":"Suivi et/ou pronostic","t":"Connaître le mode évolutif des hépatites virales","q":"Décrivez le risque de chronicité de l'hépatite B (VHB) en fonction de l'âge à la contamination.","a":"<p>Le risque de chronicité du VHB est inversement proportionnel à l'âge au moment de la contamination :</p><ul><li>Chez le <strong>nouveau-né</strong> : <strong>90 %</strong></li><li>Chez l'<strong>enfant</strong> : <strong>30 %</strong></li><li>Chez l'<strong>adulte</strong> : <strong>10 %</strong></li></ul><p>On observe une guérison spontanée d'environ 90% des hépatites aiguës chez l'adulte, ce qui correspond à un taux de chronicité de 10%.</p>"}]};